        //
        function createSummaryAndThumb(pID) {
            $(pID).attr("class", " trigger effect-slidefromleft");

            const div = document.getElementById(pID);
            const datetime = $(div).closest('body').find("h2.date-header").text(); // hoặc parent chain
			console.log("pID =", pID);
            let imgtag = "";

            const img = div.getElementsByTagName("img");

            const summ = summary_img; // giả sử summary_img đã có sẵn

            const title = $(div).parent().find("h3.post-title").html();
            const postUrl = $(div).parent().find("h3.post-title a").attr("href")

            if (img.length > 0) {
                imgtag = `
                    <div class="home-post-image" style="margin-right: 15px !important; max-height: 100px;">

                        <a href="${postUrl}" title="${$(div).parent().find("h3.post-title").text().trim()}" style="display: block; height: 100%;">

                            <img src="${img[0].src}" alt="${$(div).parent().find("h3.post-title").text().trim()}" style="width: 160px;height: 100px;object-fit: cover; box-shadow: none;"/>

                        </a>

                    </div>`;
            }


            let snippet = removeHtmlTag(div.innerHTML, summ).replace(/createSummaryAndThumb.*../, '');
            snippet = snippet.replace(/&nbsp;/g, '');


            snippet = snippet.split("●")
            var phonenumber = snippet[0]
            var address = snippet[1]

            // Dùng template literal cho container chính
            const summaryWithTitle = `
              <div class="img-except" style="display: flex; align-items: center;">
                  ${imgtag}
                  <div class="except" style="padding: 0; flex: 1;">
                      <h3 class="post-title manh__vb" style="font-weight:600; margin: 0px !important;" translate="no">
                          ${title}
                      </h3>
                      <div class="priority-text" style="font-size:14px; color:#555; line-height:1.4;">
                        <!-- Hàng trên: phonenumber + address -->
                        <div style="">
                          <span><a style="color: #218d44;font-size: 1.35rem;" href="tel:${phonenumber}">${phonenumber}</a></span>
                          <span style="color: #000000;">${address}</span>
                        </div>
                      </div>
                  </div>
              </div>`;


            // Gán lại cho div post-body
            div.innerHTML = `${summaryWithTitle} ...`;

            // Thêm container ngoài posts-home-page + ngày đăng
            $(div).parent().html(`
                  <div class="posts-home-page post-body entry-content">    
                      ${summaryWithTitle}
                  </div>
              `);
        }

