function createSummaryAndThumbNEWS(pID) {
    $(pID).attr("class", " trigger effect-slidefromleft");
    var div = document.getElementById(pID);

    var author = "";
    var imgtag = "";
    var img = div.getElementsByTagName("img");
    var summ = summary_noimg;
    var content = removeHtmlTag(div.innerHTML, summ)
    content = content.replace(/&nbsp;/g, '').trim();
    let postUrl = $(div).parent().find("h3.post-title a").attr("href")

    imgtag =
        '<a href="' + postUrl + '" class="home-post-image" style="margin-right: 10px; height: 100%;display:block;">' +
        '<div data-original="' + img[0].src + '" style="">' +
        '<img src="' + img[0].src + '" alt="" style="width: 160px;height: 100px;margin-left: 0;object-fit: cover;" />' +
        '</div>' +
        '</a>';

    summ = summary_img;

    // Tạo container chính flexbox
    var summaryWithTitle = "<div class='img-except' style='display: flex; align-items: flex-start;'> ";

    // Thêm ảnh bên trái
    summaryWithTitle += imgtag;

    summaryWithTitle += "<div class='except' style='padding: 0 0 0 1.25rem; flex: 1;'> \
            <h3 class='post-title manh__vb' style='margin: 0!important; color: black;'>"
        + $(div).parent().find("h3.post-title").html() +
        "</h3> \
            <div class='post-meta' style='font-size: 1.25rem; opacity: 0.8;'>"
        + content.slice(0, 250) +
        "...</div> \
        </div>";


    summaryWithTitle += "</div>";

    // Xóa đoạn script cũ trong content nếu có
    summaryWithTitle = summaryWithTitle.replace(/createSummaryAndThumbNEWS.*../, '');

    // Gán lại cho div post-body
    div.innerHTML = summaryWithTitle + " ...";

    // Thêm container ngoài posts-home-page + ngày đăng
    $(div).parent().html(
        "<div class='posts-home-page post-body entry-content'>" +
        summaryWithTitle +
        "</div>"
    );
}
