    var img = div.getElementsByTagName("img");
    var summ = summary_noimg;

    let temp = removeHtmlTag(div.innerHTML, summ).replace(/createSummaryAndThumbBelow.*../, '')
    temp = temp.split("●")
    const phonenumber = temp[0] ? temp[0].trim() : "";
    const address = temp[1] ? temp[1].trim() : "";
    const mainAddress = temp[2] ? temp[2].trim() : "";

    var iframe = $(div).parent().find("iframe") ? $(div).parent().find("iframe") : "";


    const summaryWithTitle = `
          <div class='img-except'  style='display:flex; align-items:flex-start; gap:1rem;'>

              <!-- Icon bên trái -->
              <div class='icon-left' id="${$(div).parent().find("h3.post-title").text().trim()}" data-content='"${iframe.prop("outerHTML")}"' style='flex-shrink:0;'>${icon}</div>

              <!-- Nội dung bên phải -->
              <div class='except' style='flex:1; display:flex; flex-direction:column;'>

                  <!-- Hàng 1: Title -->
                  <h3 class='post-title manh__vb' style='margin:0!important; font-weight:bold!important; font-size: 1.4rem;' translate="no">
                      ${$(div).parent().find("h3.post-title").html()}
                  </h3>
                  <!-- Hàng 2: Phonenumber + Address -->
                  <div class='contact-info' style='margin:2px 0; font-size:1.4rem; color:#555;'>
                      <span><a style="color: #218d44;font-size: 1.35rem;" href="tel:${phonenumber}">${phonenumber.replace(/&nbsp;/g, '')}</a></span>
      					<span style="color: #000000;">${address.replace(/&nbsp;/g, '')}</span>
                  </div>
              </div>
          </div>
          `;
    div.innerHTML = summaryWithTitle;
}
