document.addEventListener("DOMContentLoaded", function () {
    var ul;
    ul = document.querySelector("#Label2 ul");
    if (ul) {
        ul.id = "yellow-detailed";
        ul.className = "detailed"
    }
    const yellow = document.getElementById("yellow");
    if (yellow) {
        yellow.appendChild(ul);
    }

    ul = document.querySelector("#Label3 ul");
    if (ul) {
        ul.id = "news-detailed";
        ul.className = "detailed"
    }
    const news = document.getElementById("news");
    if (news) {
        news.appendChild(ul);
    }
});
