document.addEventListener("DOMContentLoaded", function () {
    const posts = document.querySelectorAll("#news-list .post-outer");
    const perPage = 8;
    const totalPages = Math.ceil(posts.length / perPage);
    let currentPage = 1;

    const paginationContainer = document.getElementById("news-pagination");

    function showPage(page) {
        // 1️⃣ Ẩn ngay các post cũ
        posts.forEach(p => {
            p.style.display = "none";
            p.style.opacity = 0;
        });

        // 2️⃣ Hiển thị post mới với fade in
        const start = (page - 1) * perPage;
        const end = page * perPage;
        for (let i = start; i < end && i < posts.length; i++) {
            const p = posts[i];
            p.style.display = "block";
            p.style.opacity = 0;
            // fade in
            setTimeout(() => { p.style.opacity = 1; }, 10); // delay nhỏ để trigger transition
        }

        // 3️⃣ Highlight số trang
        const pageNumbers = paginationContainer.querySelectorAll(".page-number");
        pageNumbers.forEach((numEl, idx) => {
            numEl.classList.toggle("current", idx + 1 === page);
        });
    }

    function createPagination() {
        paginationContainer.innerHTML = "";

        const prev = document.createElement("span");
        prev.setAttribute("translate", "no");
        prev.className = "page-arrow";
        prev.innerText = "<";
        prev.addEventListener("click", () => {
            if (currentPage > 1) {
                currentPage--;
                showPage(currentPage);
            }
        });
        paginationContainer.appendChild(prev);

        for (let i = 1; i <= totalPages; i++) {
            const num = document.createElement("span");
            num.setAttribute("translate", "no");
            num.className = "page-number";
            num.innerText = i;
            num.addEventListener("click", () => {
                currentPage = i;
                showPage(currentPage);
            });
            paginationContainer.appendChild(num);
        }

        const next = document.createElement("span");
        next.setAttribute("translate", "no");
        next.className = "page-arrow";
        next.innerText = ">";
        next.addEventListener("click", () => {
            if (currentPage < totalPages) {
                currentPage++;
                showPage(currentPage);
            }
        });
        paginationContainer.appendChild(next);
    }

    createPagination();

    // khởi tạo hiển thị trang 1
    showPage(currentPage);

    if (window.innerWidth < 1200) {
        const div = document.querySelector("#Blog3 #news-list");

        let startX = 0;
        let endX = 0;

        div.addEventListener("touchstart", (e) => {
            startX = 0;
            endX = 0;
            startX = e.touches[0].clientX;
        });

        div.addEventListener("touchend", (e) => {
            endX = e.changedTouches[0].clientX;
            const diffX = endX - startX;

            if (Math.abs(diffX) > 80) { // threshold 50px
                if (diffX > 0) {
                    if (currentPage > 1) {
                        currentPage--;
                        showPage(currentPage)
                    }
                } else {
                    if (currentPage < totalPages) {
                        currentPage++;
                        showPage(currentPage)
                    }
                }
            }
        });
    }
});

