function swapBlogs() {
    const blog2 = document.getElementById('Blog2');
    const blog3 = document.getElementById('Blog3');

    if (!blog2 || !blog3) return;

    if (window.innerWidth < 992) {
        // Swap nếu chưa swap
        if (!blog2.dataset.swapped) {
            const temp = blog2.innerHTML;
            blog2.innerHTML = blog3.innerHTML;
            blog3.innerHTML = temp;

            blog2.dataset.swapped = "true";
            blog3.dataset.swapped = "true";
        }
    } else {
        // Swap lại về vị trí gốc nếu đã swap
        if (blog2.dataset.swapped) {
            const temp = blog2.innerHTML;
            blog2.innerHTML = blog3.innerHTML;
            blog3.innerHTML = temp;

            delete blog2.dataset.swapped;
            delete blog3.dataset.swapped;
        }
    }
}

// Gọi khi load trang
swapBlogs();

// Gọi khi resize
window.addEventListener('resize', swapBlogs);

