        const category = document.getElementById("category-content");
        const mobileNav = document.querySelector("nav.mobile-navigation");

        if (!category || !mobileNav) return;

        if (window.innerWidth < 768) {
            // thêm class và id nếu chưa có
            if (!category.classList.contains("primary-menu-mobile")) {
                category.classList.add("primary-menu-mobile");
            }

            // chuyển vào nav.mobile-navigation nếu chưa ở đó
            if (category.parentElement !== mobileNav) {
                mobileNav.appendChild(category);
            }
        } else {
            // nếu màn hình lớn, có thể đưa category về vị trí cũ (tuỳ nhu cầu)
            // ví dụ: document.querySelector(".original-parent").appendChild(category);
        }
