document.addEventListener("DOMContentLoaded", function () {
    let elementsRearranged = false;

    function moveElementsForMobile() {
        const blog2 = document.getElementById("Blog2");
        const blog3 = document.getElementById("Blog3");
        const category = document.getElementById("Label1"); // Category widget
        const stats1 = document.getElementById("Stats1"); // Map widget
        const label3 = document.getElementById("Label3"); // Labels widget

        if (!blog2 || !blog3 || !category || !stats1) return;

        const sidebarSection = stats1.parentElement;
        const mainSection = blog2.parentElement; // col-md-9 section

        if (window.innerWidth < 768) {
            if (!elementsRearranged) {
                // Thứ tự mong muốn: Blog3 → Category → Blog2 → Map
                // Đưa Blog3 lên đầu sidebar (sau Label3 nếu có)
                if (label3) {
                    sidebarSection.insertBefore(blog3, label3.nextSibling);
                } else {
                    sidebarSection.insertBefore(blog3, sidebarSection.firstChild);
                }

                // Đưa Category sau Blog3
                sidebarSection.insertBefore(category, blog3.nextSibling);

                // Đưa Blog2 sau Category
                sidebarSection.insertBefore(blog2, category.nextSibling);

                // Map (Stats1) sau Blog2
                sidebarSection.insertBefore(stats1, blog2.nextSibling);

                elementsRearranged = true;
            }
        } else {
            if (elementsRearranged) {
                // Đưa về thứ tự gốc
                // Blog2 về lại main section
                mainSection.appendChild(blog2);

                // Sidebar: Label3 → Stats1 → Label1 → Blog3
                if (label3) {
                    sidebarSection.insertBefore(stats1, label3.nextSibling);
                } else {
                    sidebarSection.insertBefore(stats1, sidebarSection.firstChild);
                }
                sidebarSection.insertBefore(category, stats1.nextSibling);
                sidebarSection.insertBefore(blog3, category.nextSibling);

                elementsRearranged = false;
            }
        }
    }

    // Chạy khi load
    moveElementsForMobile();

    // Chạy khi resize
    window.addEventListener("resize", moveElementsForMobile);
});
