document.addEventListener("DOMContentLoaded", function () {
    function initMobileDropdown() {
        if (window.innerWidth >= 768) return; // chỉ chạy trên mobile

        const category = document.getElementById("category-content");
        if (!category) return;

        // lấy tất cả li có ul con
        const items = category.querySelectorAll("li > ul");

        items.forEach(submenu => {
            const parentLi = submenu.parentElement;

            parentLi.addEventListener("click", function (e) {
                e.stopPropagation();  // không lan click lên cha
                submenu.classList.toggle("max-height-dropdown");
            });
        });
    }

    initMobileDropdown();
    window.addEventListener("resize", initMobileDropdown);
});



